class AsyncCache {
    constructor() {
        this.a = new Map();
    }
    set(key, promise) {
        this.a.set(key, new PromiseWithSyncAccess(promise));
    }
    get(key) {
        return this.a.get(key)?.promise;
    }
    getSyncIfCached(key) {
        return this.a.get(key)?.result?.data;
    }
    isCached(key) {
        return this.a.get(key)?.result !== undefined;
